ate-columns: 1fr 3fr;\r\n  gap: 10px;\r\n\r\n  color: $ColorText1;\r\n  background: $BGColor2;\r\n  border-radius: $BR-Middle;\r\n\r\n\r\n\r\n\r\n}\r\n\r\n.image {\r\n  padding: 10px;\r\n  \r\n  width: 100%;\r\n  height: 100%;\r\n\r\n  min-height: 0;\r\n\r\n  & img {\r\n    width: 100%; \r\n    height: 100%; \r\n    object-fit: contain; \r\n \r\n  }\r\n}\r\n\r\n.content {\r\n  height: 100%;\r\n  padding: 10px;\r\n  min-height: 0;\r\n\r\n  display: flex;\r\n  flex-direction: column;\r\n  justify-content: space-between;\r\n}\r\n\r\n.header {\r\n  margin: 0px 0px 20px 0px;\r\n\r\n  display: flex;\r\n  align-items: center;\r\n  justify-content: space-between;\r\n}\r\n\r\n.name {\r\n  @include text(20px, 600, 150%);\r\n}\r\n\r\n.controlPanel {\r\n  display: flex;\r\n  column-gap: 5px;\r\n\r\n  @include text(30px, 400, 1);\r\n\r\n  & * {\r\n    padding: 5px;\r\n\r\n    cursor: pointer;\r\n    border: $Border1;\r\n  }\r\n}\r\n\r\n.description {\r\n  width: 100%;\r\n  //height: 100%;\r\n  flex: 0 1 auto;\r\n\r\n  margin: 0px 0px 20px 0px;\r\n\r\n  @include text(16px, 400, 140%);\r\n\r\n  -webkit-line-clamp: 4;\r\n    line-clamp: 4;\r\n    display: -webkit-box;\r\n    -webkit-box-orient: vertical;\r\n    overflow: hidden;\r\n    text-overflow: ellipsis;\r\n\r\n \r\n  \r\n}\r\n\r\n.footer {\r\n  display: flex;\r\n  justify-content: end;\r\n  align-items: center;\r\n}","//----- Colors -----\r\n$BGColor1: #1D2F30;\r\n$BGColor2: #0B1919;\r\n$BGColor3: #5b5b5b;\r\n$BGColor4: #222222;\r\n\r\n$BGColor5: #121227;\r\n$BGColor6: #3c4616;\r\n$BGColor7: #0000004e; //module bg\r\n\r\n$IsRightColor: #145e22;\r\n$IsWrongColor: #5e1814;\r\n\r\n$color1: #BAE249;\r\n$color2: #c56a1f;\r\n$color3: #ccbe7c;\r\n\r\n$ColorText1: white;\r\n$ColorLink1: #42c3ff;\r\n\r\n//----- Borders -----\r\n$BR-Small: 5px;\r\n$BR-Middle: 10px;\r\n$BR-Big: 20px;\r\n\r\n$Border1: 1px solid #ffffff;\r\n$Border2: 2px solid $color2;\r\n$Border3: 2px solid #ffffff;\r\n\r\n//----- mixins -----\r\n@mixin text($fz, $fw, $lh) {\r\n  font-size: $fz;\r\n  font-weight: $fw;\r\n  line-height: $lh;\r\n}\r\n\r\n@mixin editor {\r\n\r\n  display: flex;\r\n  flex-direction: column;\r\n  row-gap: 20px;\r\n\r\n  .header {\r\n    display: flex;\r\n    justify-content: space-between;\r\n    align-items: center;\r\n  }\r\n\r\n  .title {\r\n    @include text(20px, 600, 150%)\r\n  }\r\n\r\n  .input {\r\n    border: 1px solid #ffffff;\r\n    background-color: transparent;\r\n    color: #ffffff;\r\n    padding: 10px;\r\n    @include text(20px, 400, 150%)\r\n  }\r\n\r\n  .footer {\r\n    display: flex;\r\n    justify-content: end;\r\n    align-items: center;\r\n  }\r\n}\r\n\r\n@mixin EditorBlock {\r\n  width: 100%;\r\n  padding: 10px 0px;\r\n\r\n  display: flex;\r\n  flex-direction: column;\r\n  row-gap: 20px;\r\n\r\n  .header {\r\n    display: flex;\r\n    align-items: center;\r\n    justify-content: space-between;\r\n  }\r\n\r\n  .close {\r\n    @include close;\r\n  }\r\n\r\n  .text {\r\n    color: $ColorText1;\r\n    @include text(20px, 600, 1);\r\n  }\r\n\r\n  .icon {\r\n    margin: 0px 6px 6px 0px;\r\n    display: flex;\r\n    justify-content: end;\r\n\r\n    &__image {\r\n      text-align: center;\r\n      color: $ColorText1;\r\n      @include text(20px, 400, 1);\r\n    }\r\n  }\r\n\r\n  .buttonSave {\r\n    display: flex;\r\n    justify-content: end;\r\n  }\r\n}\r\n\r\n@mixin PininField {\r\n  padding: 10px;\r\n  width: 100%;\r\n  height: 160px;\r\n\r\n  display: flex;\r\n  justify-content: center;\r\n  align-items: center;\r\n  column-gap: 3px;\r\n\r\n  border-radius: $BR-Middle;\r\n  background: $BGColor3;\r\n  text-align: center;\r\n}\r\n\r\n@mixin PininAnswers {\r\n  display: flex;\r\n  justify-content: center;\r\n  align-items: center;\r\n  column-gap: 10px;\r\n  flex-wrap: wrap;\r\n}\r\n\r\n@mixin close {\r\n  font-size: 26px;\r\n}\r\n\r\n@mixin WithoutArrows {\r\n\r\n  /* Убираем стрелки в Chrome, Safari, Edge и других WebKit-браузерах */\r\n  &::-webkit-outer-spin-button,\r\n  &::-webkit-inner-spin-button {\r\n    -webkit-appearance: none;\r\n    margin: 0;\r\n  }\r\n\r\n  /* Убираем стрелки в Firefox */\r\n  -moz-appearance: textfield;\r\n}\r\n\r\n//Ограничение строк:\r\n@mixin LineClamp($N) {\r\n  -webkit-line-clamp: $N;\r\n  line-clamp: $N;\r\n  display: -webkit-box;\r\n  -webkit-box-orient: vertical;\r\n  overflow: hidden;\r\n}\r\n\r\n//Для страниц в админке:\r\n\r\n@mixin adminBlock {\r\n  padding: 20px 10px;\r\n\r\n  background: $BGColor4;\r\n  border-radius: $BR-Middle;\r\n  border: $Border1;\r\n}\r\n\r\n\r\n@mixin adminPage {\r\n  @include adminBlock;\r\n\r\n  .h2 {\r\n    margin: 0px 0px 30px 0px;\r\n    @include text(24px, 600, 1);\r\n  }\r\n\r\n  .dataModules {\r\n    display: flex;\r\n    flex-direction: column;\r\n    row-gap: 30px;\r\n  }\r\n}\r\n\r\n\r\n@mixin nuvItem {\r\n  padding: 5px 5px;\r\n  width: 100%;\r\n  height: 24px;\r\n  \r\n  display: flex;\r\n  align-items: center;\r\n  justify-content: space-between;\r\n\r\n  background-color: $BGColor6;\r\n  border-radius: $BR-Small;\r\n  cursor: pointer;\r\n  transition: all 0.3s ease 0s;\r\n\r\n  &_active {\r\n    background-color: lighten($BGColor6, 20%);\r\n\r\n    @media (min-width: 768px) {\r\n      &:hover {\r\n        background-color: lighten($BGColor6, 20%);\r\n      }\r\n    }\r\n  }\r\n\r\n  @media (min-width: 768px) {\r\n    &:hover {\r\n      background-color: lighten($BGColor6, 20%);\r\n    }\r\n  }\r\n\r\n}\r\n\r\n@mixin nuvItemFull {\r\n  @include nuvItem;\r\n  \r\n  & .icon {\r\n    font-size: 12px;\r\n  }\r\n\r\n  & .text {\r\n    @include text(14px, 600, 1);\r\n  }\r\n\r\n  & .settings {\r\n    display: flex;\r\n    column-gap: 3px;\r\n  }\r\n}\r\n\r\n@mixin creatorFooter {\r\n  height: 50px;\r\n  padding: 10px;\r\n\r\n  display: flex;\r\n  justify-content: end;\r\n  align-items: center;\r\n\r\n  background: $BGColor6;\r\n  color: $ColorText1;\r\n\r\n  &__text {\r\n    flex: 1 0 auto;\r\n    @include text(20px, 600, 100%);\r\n    text-align: center;\r\n  }\r\n}\r\