import React, { useEffect, useState } from 'react'
import styles from './AboutMePageEditor.module.scss'
import DataModule from '../../DataModule/DataModule'
import { useSelector } from 'react-redux'
import Button from '../../../../UI/Button/Button'
import ReactQuill from 'react-quill'
import ImageUpload from '../../../../UI/ImageUpload/ImageUpload'
import ServiseInput from '../../../../UI/ServiseInput/ServiseInput'

const AboutMePageEditor = () => {

  const AboutPageData = useSelector(state => state.data.data.aboutPage)
  const [blocks, setBlocks] = useState([])
  const [youTubeVideoLink, setYouTubeVideoLink] = useState("")
  const [text, setText] = useState("")

  const handleImageChange = (index, value) => {



    setBlocks(prevBlocks =>
      prevBlocks.map((block, i) =>
        i === index ? { ...block, image: value } : block
      )
    );
  };

  const handleTextChange = (index, value) => {
    setBlocks(prevBlocks =>
      prevBlocks.map((block, i) =>
        i === index ? { ...block, text: value } : block
      )
    );
  };

  const addBlock = () => {
    setBlocks(prevBlocks => [
      ...prevBlocks,
      {
        image: "",
        text: ""
      }
    ]);
  }

  const deleteBlock = (index) => {
    setBlocks(prevBlocks => prevBlocks.filter((_, i) => i !== index))
  }

  useEffect(() => {
    if (AboutPageData !== undefined) {
      setBlocks(AboutPageData.blocks)
      setYouTubeVideoLink(AboutPageData.youTubeVideoLink)
      setText(AboutPageData.text)
    }
  }, [AboutPageData])

  return (
    <div className={styles.mainData}>
      <h2 className={styles.h2}>About Page</h2>
      <div className={styles.dataModules}>
        <DataModule
          headerText="Blocks:"
          dataType="aboutPage"
          dataName="blocks"
          data={blocks}
        >
          <div className={styles.blocks}>
            {blocks.map((item, index) => (
              <div key={index} className={styles.block}>
                <div className={styles.delete}
                  onClick={() => deleteBlock(index)}
                >X</div>
                <ImageUpload
                  storagePath="data/aboutPage"
                  oldLink={item.image}
                  getLink={(link) => { handleImageChange(index, link) }}
                  fileExt={["jpg", "jpeg", "png", "gif", "webp"]}
                />
                <ReactQuill
                  theme="snow"
                  value={item.text}
                  onChange={(value) => { handleTextChange(index, value) }}
                  modules={{
                    toolbar: [
                      // [{ 'font': [] }],
                      [{ 'size': ['small', false, 'large', 'huge'] }],
                      [{ 'header': '1' }, { 'header': '2' }],
                      [{ 'list': 'ordered' }, { 'list': 'bullet' }],
                      ['bold', 'italic', 'underline'],
                      [{ 'align': [] }],
                      ['link',],
                      ['clean']
                    ],
                  }}
                />
              </div>
            ))}
            <div className={styles.buttonContainer}>
              <Button
                text="Add block"
                onClick={() => addBlock()}
              />
            </div>
          </div>
        </DataModule>
        <DataModule
          headerText="YouTube-Video:"
          dataType="aboutPage"
          dataName="youTubeVideoLink"
          data={youTubeVideoLink}
        >
          <ServiseInput
            value={youTubeVideoLink}
            onChange={(e) => setYouTubeVideoLink(e.target.value)}
          />
        </DataModule>
        <DataModule
          headerText="Text:"
          dataType="aboutPage"
          dataName="text"
          data={text}
        >
          <ReactQuill
            theme="snow"
            value={text}
            onChange={(value) => { setText(value) }}
            modules={{
              toolbar: [
                // [{ 'font': [] }],
                [{ 'size': ['small', false, 'large', 'huge'] }],
                [{ 'header': '1' }, { 'header': '2' }],
                [{ 'list': 'ordered' }, { 'list': 'bullet' }],
                ['bold', 'italic', 'underline'],
                [{ 'align': [] }],
                ['link',],
                ['clean']
              ],
            }}
          />
        </DataModule>
      </div>
    </div>
  )
}

export default AboutMePageEditor