import React from 'react'
import styles from './StepCreator.module.scss'
import { useDispatch, useSelector } from 'react-redux'
import { deleteModule, moveDownModule, moveUpModule, saveModule } from '../../../../store/course/course'
import ContentBlockAdmin from '../../../Common/ContentBlockAdmin/ContentBlockAdmin'
import { AUDIO, EXERSIZE_PININ_1, EXERSIZE_PININ_2, IMAGE,
  NEXT_STEP_BUTTON, PREV_STEP_BUTTON, QUIZ_TEXT_INPUT,
  TEST_CHECKBOX, TEST_RADIO,
  TEXT, VIDEO } from '../../../../utils/contentTypes'
import CreationPanel from '../../../UI/CreationPanel/CreationPanel'

const StepCreator = ({ courseName }) => {

  const dispatch = useDispatch()
  const steps = useSelector(state => state.course.steps)
  const stepNumber = useSelector(state => state.course.stepNumber)

  const handleSaveContent = (value, contentType, moduleNumber) => {
    dispatch(saveModule({
      stepNumber: stepNumber,
      moduleNumber: moduleNumber,
      module: {
        contentType: contentType,
        content: value,
      }
    }))
  }

  const moveUp = (index) => {
    if (index > 0) {
      dispatch(moveUpModule({ moduleNumber: index }))
    }
  }

  const moveDown = (index) => {
    if (index < steps[stepNumber].modules.length - 1) {
      dispatch(moveDownModule({ moduleNumber: index }))
    }
  }

  const deleteItem = (index) => {
    let result = window.confirm("Вы уверены что хотите удалить?");
    if (result) dispatch(deleteModule({ moduleNumber: index }))
  }

  return (
    <div>
      <div className={styles.contents}>
        {stepNumber !== steps.length &&
          steps[stepNumber].modules.map((item, index) => (
            <ContentBlockAdmin
              key={index}
              index={index}
              contentType={item.contentType}
              content={item.content}
              onMoveUp={() => moveUp(index)}
              onMoveDown={() => moveDown(index)}
              onDelete={() => deleteItem(index)}
              onSave={(value, contentType) => { handleSaveContent(value, contentType, index) }}
              onClose={() => { }}
              isEditorOn={false}
              reset={stepNumber}
              infoForPath={{  //нужно для сохранения файлов в storage
                type: "courses",
                name: courseName,
              }}
            />
          ))
        }
      </div>
      {steps.length > 0 &&
        <CreationPanel
          onSaveInStorage={() => {}}
          onSave={(value, contentType) => {
            handleSaveContent(value, contentType, steps[stepNumber].modules.length)
          }}
          reset={stepNumber}
          index={steps[stepNumber].modules.length}
          modules={[AUDIO, EXERSIZE_PININ_1, EXERSIZE_PININ_2, IMAGE,
            NEXT_STEP_BUTTON, PREV_STEP_BUTTON, QUIZ_TEXT_INPUT,
            TEST_CHECKBOX, TEST_RADIO,
            TEXT, VIDEO]}
            infoForPath={{  //нужно для сохранения файлов в storage
              type: "courses",
              name: courseName,
            }}
        />
      }
    </div>
  )
}

export default StepCreator