import React, { useEffect, useState } from 'react'
import styles from './DataFileModule.module.scss'
import FileUpload from '../../../UI/FileUpload/FileUpload'
import { useSaveData } from '../../../../utils/firebaseFunctions';

const DataFileModule = ({  ...props}) => {

	const { savePageData, isWaitingSaveData, isSuccessfulSaveData } = useSaveData();
  const [link, setLink] = useState("")

	const saveData = (link) => {
    savePageData(props.dataType, {[props.dataName]: link});
  }

  useEffect(() => {
    setLink(props.link)
  }, [props.link])

  return (
    <div className={styles.dataFileModule}>
			<div className={styles.headerText}>{props.headerText}</div>
          <div className={styles.body}>
            <FileUpload
              storagePath={props.storagePath}
              oldLink={props.link}
              getLink={(link) => { saveData(link) ; setLink(link) }}
              fileExt={props.fileExt}
            />
            <div className={styles.promoImage}>
              <img src={link} alt="propmoImage" />
            </div>
          </div>
    </div>
  )
}

export default DataFileModule