import React, { useEffect, useState } from 'react';
import styles from './HtmlEditor.module.scss'
import 'react-quill/dist/quill.snow.css';
import { FaWindowClose } from 'react-icons/fa';
import InputArea from '../../InputArea/InputArea';

const HtmlEditor = ({ changeContent, onClose, content = {} }) => {

  const [htmlCode, setHtmlCode] = useState(content.htmlCode || "")

  useEffect(() => {
    changeContent({htmlCode: htmlCode})
    console.log(htmlCode)
  }, [htmlCode])

  return (
    <div className={styles.Editor}>
      <div className={styles.header}>
        <div className={styles.title}>Вставьте HTML-код:</div>
        <FaWindowClose
          className={styles.close}
          onClick={() => onClose()}
        />
      </div>
      <InputArea
        value={htmlCode}
        onChange={(e) => {setHtmlCode(e.target.value)}}
      />
    </div>
  )
};

export default HtmlEditor;