import React, { useState } from 'react'
import styles from './ImageEditor.module.scss'
import { FaWindowClose } from 'react-icons/fa'
import ServiseInput from '../../ServiseInput/ServiseInput'
import FileUpload from '../../FileUpload/FileUpload'

const ImageEditor = ({ changeContent, onClose, content = {}, infoForPath }) => {

  const [link, setLink] = useState(content.link || "")
  const [size, setSize] = useState(content.size || 100)

  const saveLink = (link) => {
    setLink(link)
    changeContent({ link: link, size: size })
  }

  const saveSize = (size) => {
    setSize(size)
    changeContent({ link: link, size: size })   
  }

  return (
    <div className={styles.editor}>
      <div className={styles.header}>
        <div className={styles.title}>Добавте ссылку на изображение:</div>
        <FaWindowClose
          className={styles.close}
          onClick={() => onClose()}
        />
      </div>
      <FileUpload
        storagePath={`images/${infoForPath.type}/${infoForPath.name}`}
        oldLink={content.link}
        getLink={(link) => { saveLink(link) }}
        fileExt={["jpg", "jpeg", "png", "gif", "webp"]}
      />
      <div className={styles.title}>Выберите Max Width (%): </div>
      <ServiseInput
        type="number"
        value={size}
        onChange={(e) => saveSize(e.target.value)}
        disabled={link ? false : true}
      />
    </div>
  )
}

export default ImageEditor