import React, { useEffect, useState } from 'react'
import styles from './BarItem.module.scss'
import { FaArrowAltCircleDown, FaArrowAltCircleUp, FaPencilAlt } from 'react-icons/fa'
import { MdDelete } from 'react-icons/md'

const BarItem = ({activeItem, onRename, onMoveUp, onMoveDown, onDelete, ...props}) => {

  const [isActiv, setIsActiv] = useState(false)

  useEffect(() => {
    if (props.index === activeItem) {
      setIsActiv(true)
    } else {
      setIsActiv(false)
    }
  }, [activeItem])

  const rename = (event) => {
    event.stopPropagation();
    let newStepName = prompt('Введите текст:', props.text);
    if (newStepName && newStepName !== props.text) {
      onRename(newStepName)
    }
  }

  const moveUp = (event) => {
    event.stopPropagation();
    onMoveUp()
  }

  const moveDown = (event) => {
    event.stopPropagation();
    onMoveDown()
  }

  const deleteItem = (event) => {
    event.stopPropagation();
    let result = window.confirm("Вы уверены что хотите удалить?");
    if (result) onDelete()
  }

  return (
    <div
      className={isActiv
        ? styles.sidebarItem + " " + styles.sidebarItem_active
        : styles.sidebarItem
      }
      onClick={props.onClick}
    >
      <div className={styles.text}>{props.text}</div>
      <div className={styles.settings}>
        <FaPencilAlt
          className={styles.icon}
          onClick={rename}
        />
        <FaArrowAltCircleUp
          className={styles.icon}
          onClick={moveUp}
        />
        <FaArrowAltCircleDown
          className={styles.icon}
          onClick={moveDown}
        />
        <MdDelete
          className={styles.icon}
          onClick={deleteItem}
        />
      </div>
    </div>
  )
}

export default BarItem