import React, { useState } from 'react';
import styles from './SiteEditorPage.module.scss';
import Container from '../../Common/Container/Container';
import { ABOUT_PAGE_EDITOR, ABOUTMEBLOCK_DATA, adminRoutes,  MAIN_DATA } from '../../../adminRouts';


const SiteEditorPage = () => {

  const [page, setPage] = useState(MAIN_DATA) 

   const currentRoute = adminRoutes.find(route => route.path === page);

  return (
    <div className={styles.adminPage}>
      <Container className={styles.container}>
        <h1 className={styles.h1}>Admin Panel</h1>
          <ul className={styles.nuv}>
            {adminRoutes.map((item) => (
              <li key={item.path} onClick={() => setPage(item.path)}>{item.name}</li>
            ))}
          </ul>
          <div className={styles.main}>
            {currentRoute && <currentRoute.Component />}
          </div>
      </Container>
    </div>
  );
};

export default SiteEditorPage;
