import React from 'react'
import styles from './ControlPanel.module.scss'
import { FaArrowAltCircleDown, FaArrowAltCircleUp, FaPencilAlt } from 'react-icons/fa'
import { MdDelete } from 'react-icons/md'

const ControlPanel = ({onEdit, onMoveUp, onMoveDown, onDeleteItem}) => {

  return (
    <div className={styles.controlPanel}>
      <FaPencilAlt
        className={styles.icon}
        onClick={() => onEdit()}
      />
      <FaArrowAltCircleUp
        className={styles.icon}
        onClick={() => onMoveUp()}
      />
      <FaArrowAltCircleDown
        className={styles.icon}
        onClick={() => onMoveDown()}
      />
      <MdDelete
        className={styles.icon}
        onClick={() => onDeleteItem()}
      />
    </div>
  )
}

export default ControlPanel