import React, { useEffect, useState } from 'react'
import styles from './ContactPageEditor.module.scss'
import DataModule from '../../DataModule/DataModule'
import { useSelector } from 'react-redux'
import ReactQuill from 'react-quill'

const ContactPageEditor = () => {

  const contactPageData = useSelector(state => state.data.data.contactPage)
  const [text, setText] = useState("");


  useEffect(() => {
    if (contactPageData !== undefined) {
      setText(contactPageData.text)
    }
  }, [contactPageData])

  return (
    <div className={styles.mainData}>
      <h2 className={styles.h2}>Contact Page</h2>
      <div className={styles.dataModules}>
        <DataModule
          headerText="Text:"
          dataType="contactPage"
          dataName="text"
          data={text}
        >
          <ReactQuill
            theme="snow"
            value={text}
            onChange={(value) => setText(value)}
            modules={{
              toolbar: [
                // [{ 'font': [] }],
                [{ 'size': ['small', false, 'large', 'huge'] }],
                [{ 'header': '1' }, { 'header': '2' }],
                [{ 'list': 'ordered' }, { 'list': 'bullet' }],
                ['bold', 'italic', 'underline'],
                [{ 'align': [] }],
                ['link',],
                ['clean']
              ],
            }}
          />
        </DataModule>
      </div>
    </div>
  )
}

export default ContactPageEditor