import React, { useEffect, useState } from 'react'
import styles from './CourseCreator.module.scss'
import StepCreator from './StepCreator/StepCreator'
import Button from '../../UI/Button/Button'
import Container from '../../Common/Container/Container'
import { useDispatch, useSelector } from 'react-redux'
import {
  addStep,
  deleteStep,
  moveDownStep,
  moveUpStep,
  renameStep,
  setCourseDescription,
  setCourseImage,
  setCourseName,
  setStepNumber
} from '../../../store/course/course'
import { FaPencilAlt } from 'react-icons/fa'
import { useSaveCourse } from '../../../utils/firebaseFunctions'
import BarItem from '../../UI/BarItem/BarItem'
import ImageUpload from '../../UI/ImageUpload/ImageUpload'

const CourseCreator = () => {

  const { saveCourse, isWaitingSaveCourse, isSuccessfulSaveCourse } = useSaveCourse();
  const stepNumber = useSelector(state => state.course.stepNumber)
  const dispatch = useDispatch()
  const courseName = useSelector(state => state.course.courseName)
  const courseImage = useSelector(state => state.course.courseImage)
  const courseDescription = useSelector(state => state.course.courseDescription)
  const steps = useSelector(state => state.course.steps)
  const course = useSelector(state => state.course)
  const [isEditCourseName, setIsEditCourseName] = useState(false)
  const [isEditCourseDescription, setIsEditCourseDescription] = useState(false)

  const openStep = (idx, e) => {
    dispatch(setStepNumber({ stepNumber: idx }))
  }

  const createNewStep = () => {
    dispatch(setStepNumber({ stepNumber: steps.length }))
    dispatch(addStep())
  }

  const handleSaveCourse = () => {
    saveCourse(course);
  };

  const changeCourseName = (e) => {
    dispatch(setCourseName({ courseName: e.target.value }))
  }

  const changeCourseDescription = (e) => {
    dispatch(setCourseDescription({ courseDescription: e.target.value }))
  }

  const changeCourseImage = (link) => {
    dispatch(setCourseImage({ courseImage: link }))
  }

  const handleRenameStep = (index, newStepName) => {
    dispatch(renameStep({ stepIndex: index, newStepName: newStepName }))
  }

  const handleMoveUpStep = (index) => {
    if (index > 0) {
      dispatch(moveUpStep({ stepNumber: index }))
    }
  }

  const handleMoveDownStep = (index) => {
    if (index < steps.length - 1) {
      dispatch(moveDownStep({ stepNumber: index }))
    }
  }

  const handleDeleteStep = (index) => {
    dispatch(deleteStep({ stepNumber: index }))
  }

  return (
    <div className={styles.courseCreator}>
      <Container className={styles.container}>
        <div className={styles.header}>
          {isEditCourseName
            ? <div className={styles.courseName}>
              <input
                type="text"
                value={courseName}
                onChange={changeCourseName}
              />
              <Button
                text="SAVE"
                onClick={() => setIsEditCourseName(false)}
              />
            </div>
            : <div className={styles.courseName}>
              {courseName}
              <FaPencilAlt
                className={styles.courseName__icon}
                onClick={() => { setIsEditCourseName(true) }}
              />
            </div>
          }
          {isEditCourseDescription
            ? <div className={styles.courseDescription}>
              <textarea
                value={courseDescription}
                onChange={changeCourseDescription}
              ></textarea>
              <Button
                text="SAVE"
                onClick={() => setIsEditCourseDescription(false)}
              />
            </div>
            : <div className={styles.courseDescription}>
              <div className={styles.courseDescription__text}>
                {courseDescription}
              </div>
              <FaPencilAlt
                className={styles.courseDescription__icon}
                onClick={() => setIsEditCourseDescription(true)}
              />
            </div>
          }
          <div className={styles.courseImage}>

            {/* <img src={courseImage} alt="course image" />
            <FaPencilAlt
              className={styles.courseImage__icon}
              onClick={() => { changeCourseImage() }}
            /> */}

            <ImageUpload
              storagePath="courses/coursesPreview"
              oldLink={courseImage}
              getLink={(link) => { changeCourseImage(link) }}
              fileExt={["jpg", "jpeg", "png", "gif", "webp"]}
            />


          </div>
        </div>
        <div className={styles.sidebar}>
          {steps.map((item, index) => (
            <BarItem
              key={index}
              text={item.stepName}
              index={index}
              activeItem={stepNumber}
              onClick={(e) => openStep(index, e)}
              onRename={(newName) => handleRenameStep(index, newName)}
              onMoveUp={() => handleMoveUpStep(index)}
              onMoveDown={() => handleMoveDownStep(index)}
              onDelete={() => handleDeleteStep(index)}
            />
          ))}
          <div
            className={styles.addStepButton}
            onClick={() => createNewStep()}
          >+</div>
        </div>
        <div className={styles.main}>
          <StepCreator courseName={courseName} />
        </div>
        <div className={styles.footer}>
          {isWaitingSaveCourse &&
            <div className={styles.footer__text}>Сохранение курса!</div>
          }
          {isSuccessfulSaveCourse &&
            <div className={styles.footer__text}>Курс сохранен!</div>
          }
          {!isWaitingSaveCourse && !isSuccessfulSaveCourse &&
            <Button text="Save course!" onClick={handleSaveCourse} />
          }
        </div>
      </Container>
    </div>
  )
}

export default CourseCreator