import React, { useEffect, useState } from 'react'
import styles from './ExersizePininEditor.module.scss'
import ServiseInput from '../../../../../UI/ServiseInput/ServiseInput'
import Button from '../../../../../UI/Button/Button'
import { MdDelete } from 'react-icons/md'
import { FaWindowClose } from 'react-icons/fa'
import LetterAndTon from '../../../../../Common/LetterAndTon/LetterAndTon'
import ButtonAnswerTon from '../../../../../UI/ButtonAnswerTon/ButtonAnswerTon'
import { tons } from '../../../../../../utils/constForExersizes'

const ExersizePininEditor = ({changeContent, onClose, content}) => {
  
  const [variantAnswers, setVariantAnswers] = useState(
    content !== undefined ? content.variantAnswers : ["", ""]
  )
  const [isEditorTons, setIsEditorTons] = useState(false)
  const [correctAnswer, setCorrectAnswer] = useState(
    content !== undefined ? content.correctAnswer : ""
  )
  const [correctAnswerLetters, setCorrectAnswerLetters] = useState([])
  const [correctTons, setCorrectTons] = useState(
    content !== undefined ? content.correctTons : []
  )
  const [ton, setTon] = useState("")
  const [tonIsSelected, setTonIsSelected] = useState(false)

  const handleVariantAnswerChange = (index, event) => {
    const newVariantAnswers = [...variantAnswers];
    newVariantAnswers[index] = event.target.value;
    setVariantAnswers(newVariantAnswers);
  };

  const handleAddVariantAnswer = () => {
    setVariantAnswers([...variantAnswers, ""]);
  };

  const handleDeleteVariantAnswer = (index) => {
    const newVariantAnswers = [...variantAnswers];
    newVariantAnswers.splice(index, 1);
    setVariantAnswers(newVariantAnswers);
  };

  const putInInputTon = (index) => {
    // Создаем новый массив, в котором изменяем только элемент с заданным индексом
    setCorrectTons(prevState => {
      return prevState.map((item, i) => {
        if (i === index) return ton
        else return item
      })
    })
    setTonIsSelected(false)
    setTon("")
  }

  useEffect(() => {
    setCorrectAnswerLetters(correctAnswer.split(''))
    setCorrectTons(Array(correctAnswerLetters.length).fill(''))
  }, [correctAnswer, isEditorTons])

  useEffect(() => {
    changeContent({variantAnswers, correctAnswer, correctTons})
  }, [variantAnswers, correctAnswer, correctTons])

  return (
    <div className={styles.puzzleEditor}>
      <div className={styles.header}>
        <div className={styles.text}>Введите варианты ответов:</div>
        <FaWindowClose className={styles.close} onClick={() => onClose()}/>
      </div>
      {variantAnswers.map((item, index) => (
        <div key={index}>
          <div className={styles.icon}>
            <MdDelete
              className={styles.icon__image}
              onClick={() => handleDeleteVariantAnswer(index)}
            />
          </div>
          <ServiseInput
            type="text"
            value={variantAnswers[index]}
            onChange={(event) => handleVariantAnswerChange(index, event)}
          />
        </div>
      ))}
      <div className={styles.buttonAdd}>
        <Button text="+" onClick={handleAddVariantAnswer} />
      </div>
      <div className={styles.text}>Введите правильный вариант:</div>
      {!isEditorTons &&
        <ServiseInput
          type="text"
          value={correctAnswer}
          onChange={(e) => setCorrectAnswer(e.target.value)}
        />
      }
      {isEditorTons &&
        <div className={styles.field}>
          {correctAnswerLetters.map((item, index) => (
            <LetterAndTon
              key={index}
              letter={item}
              ton={correctTons[index]}
              isAnswer={false}
              onClick={() => putInInputTon(index)}
            />
          ))}
        </div>
      }
      {isEditorTons && <div className={styles.answers}>
        {tons.map((item) => (
          <ButtonAnswerTon
            key={item}
            text={item}
            onClick={(e) => {
              console.log(e.target.textContent)
              setTon(e.target.textContent)
              setTonIsSelected(true)
            }}
            tonIsSelected={tonIsSelected}
            answer2={ton}
            isAnswer={false}
          />
        ))}
      </div>}
      <div className={styles.buttonContainer}>
        {!isEditorTons && 
          <Button text="указать тонны" onClick={() => setIsEditorTons(true)}/>
        }
        {isEditorTons && 
          <Button 
            text="изменить текст" 
            onClick={() => {
              setIsEditorTons(false) 
              setCorrectTons(Array(correctAnswerLetters.length).fill(''))
            }}
          />
        }
      </div>
    </div>
  )
}

export default ExersizePininEditor