import React, { useEffect, useState } from 'react'
import styles from './MainData.module.scss'
import DataModule from '../../DataModule/DataModule'
import ServiseInput from '../../../../UI/ServiseInput/ServiseInput'
import { useSelector } from 'react-redux'

const MainData = () => {

  const mainData = useSelector( state => state.data.data.main)
  const [mainLogo, setMainLogo] = useState("");
  const [footerText, setFooterText] = useState("");

  useEffect(() => {
    if (mainData !== undefined) {
      setMainLogo(mainData.mainLogo)
      setFooterText(mainData.footerText)
    }
  }, [mainData])

  return (
    <div className={styles.mainData}>
      <h2 className={styles.h2}>Main Data</h2>
          <div className={styles.dataModules}>
            <DataModule
              headerText="Main Logo:"
              dataType="main"
              dataName="mainLogo"
              data={mainLogo}
            >
              <ServiseInput
                value={mainLogo}
                onChange={(e) => setMainLogo(e.target.value)}
              />
            </DataModule>
            <DataModule
              headerText="Footer Text:"
              dataType="main"
              dataName="footerText"
              data={footerText}
            >
              <ServiseInput
                value={footerText}
                onChange={(e) => setFooterText(e.target.value)}
              />
            </DataModule>
          </div>
    </div>
  )
}

export default MainData