import React from 'react'
import styles from './SocialComponent.module.scss'
import ServiseInput from '../../../../../UI/ServiseInput/ServiseInput';
import { MdDelete } from 'react-icons/md';
import SocialIconComponent from '../../../../../UI/SocialIconComponent/SocialIconComponent';

const SocialComponent = ({ type, link, deleteSocial, changeSocial }) => {

  return (
    <div className={styles.socialComponent}>
      <SocialIconComponent type={type} className={styles.icon} />
      <ServiseInput
        value={link}
        onChange={(e) => changeSocial(e.target.value)}
      />
      <MdDelete
        className={styles.buttonDelete}
        onClick={() => deleteSocial()}
      />
    </div>
  )
}

export default SocialComponent