import React, { useEffect, useState } from 'react'
import styles from './QuizTextInputEditor.module.scss'
import ServiseInput from '../../../../../UI/ServiseInput/ServiseInput'
import Button from '../../../../../UI/Button/Button'
import { MdDelete } from 'react-icons/md'
import { FaWindowClose } from 'react-icons/fa'

const QuizTextInputEditor = ({changeContent, onClose, content }) => {

  const [correctAnswers, setCorrectAnswers] = useState(
    content !== undefined ? content.correctAnswers : [""]
  )

  const handleCorrectAnswerChange = (index, event) => {
    const newCorrectAnswers = [...correctAnswers];
    newCorrectAnswers[index] = event.target.value;
    setCorrectAnswers(newCorrectAnswers);
  };

  const handleAddCorrectAnswer = () => {
    setCorrectAnswers([...correctAnswers, ""]);
  };

  const handleDeleteCorrectAnswer = (index) => {
    const newCorrectAnswers = [...correctAnswers];
    newCorrectAnswers.splice(index, 1);
    setCorrectAnswers(newCorrectAnswers);
  };

  useEffect(() => {
    changeContent({correctAnswers})
  }, [correctAnswers])

  return (
    <div className={styles.puzzleEditor}>
      <div className={styles.header}>
        <div className={styles.text}>Правильные ответы:</div>
        <FaWindowClose
          className={styles.close}
          onClick={() => onClose()}
        />
      </div>
      {correctAnswers.map((item, index) => (
        <div key={index}>
          <div className={styles.icon}>
            <MdDelete
              className={styles.icon__image}
              onClick={() => handleDeleteCorrectAnswer(index)}
            />
          </div>
          <ServiseInput
            type="text"
            value={correctAnswers[index]}
            onChange={(event) => handleCorrectAnswerChange(index, event)}
          />
        </div>
      ))}
      <div className={styles.buttonAdd}>
        <Button text="+" onClick={handleAddCorrectAnswer} />
      </div>
    </div>
  )
}

export default QuizTextInputEditor