import React from 'react'
import styles from './DataModule.module.scss'
import Button from '../../../UI/Button/Button'
import { useSaveData } from '../../../../utils/firebaseFunctions';

const DataModule = ({children, ...props}) => {

  const { savePageData, isWaitingSaveData, isSuccessfulSaveData } = useSaveData();
  
  const saveData = () => {
    savePageData(props.dataType, {[props.dataName]: props.data});
  }

  return (
    <div className={styles.dataModule}>
      <div className={styles.header}>
        <div className={styles.headerText}>{props.headerText}</div>
        {!isWaitingSaveData && !isSuccessfulSaveData &&
          <Button text="SAVE" onClick={() => saveData()}/>
        }
        {isWaitingSaveData && <div>Сохраняется!!!</div>}
        {isSuccessfulSaveData && <div>Соханено успешно!!!</div>}
      </div>
      {children}
    </div>
  )
}

export default DataModule