import React, { useEffect, useState } from 'react';
import styles from './YouTubeEditor.module.scss'
import 'react-quill/dist/quill.snow.css';
import { FaWindowClose } from 'react-icons/fa';
import ServiseInput from '../../ServiseInput/ServiseInput';

const YouTubeEditor = ({ changeContent, onClose, content = {} }) => {

  const [link, setLink] = useState(content.link || "")

  useEffect(() => {
    changeContent({link: link})
  }, [link])

  return (
    <div className={styles.Editor}>
      <div className={styles.header}>
        <div className={styles.title}>Введите ссылку на видео:</div>
        <FaWindowClose
          className={styles.close}
          onClick={() => onClose()}
        />
      </div>
      <ServiseInput
        value={link}
        onChange={(e) => {setLink(e.target.value)}}
      />
    </div>
  )
};

export default YouTubeEditor;