import React, { useEffect, useState } from 'react'
import styles from './MainBlockData.module.scss'
import DataModule from '../../DataModule/DataModule'
import ServiseInput from '../../../../UI/ServiseInput/ServiseInput'
import Button from '../../../../UI/Button/Button'
import { MdDelete } from 'react-icons/md'
import { useSelector } from 'react-redux'
import DataFileModule from '../../DataFileModule/DataFileModule'

const MainBlockData = () => {

  //-------------------------
  //Для текстовых данных создавать DataModule, сделать запись в  US и UF
  //Для файловых данных создавать DataFileModule. запись в US и UF не нужна
  //-------------------------

  const mainBlockData = useSelector(state => state.data.data.mainBlock)

  const [mainBlockText, setMainBlockText] = useState("");
  const [mainBlockList, setMainBlockList] = useState([]);

  const deleteMainBlockListItem = (index) => {
    setMainBlockList(mainBlockList.filter((_, i) => i !== index));
  };

  const addMainBlockListItem = () => {
    setMainBlockList([...mainBlockList, ""]);
  };

  const changeMainBlockListItem = (index, value) => {
    const newList = [...mainBlockList];
    newList[index] = value;
    setMainBlockList(newList);
  };

  useEffect(() => {
    setMainBlockText(mainBlockData.text)
    setMainBlockList(mainBlockData.list)
  }, [mainBlockData])

  return (
    <div className={styles.mainBlockData}>
      <h2 className={styles.h2}>Main Block Data</h2>
      <div className={styles.dataModules}>
        <DataFileModule
          headerText="Выберите Main Block BG:"
          dataType="mainBlock"
          dataName="BG"
          storagePath="data/mainBlock"
          link={mainBlockData.BG}
          fileExt={["jpg", "jpeg", "png", "gif", "webp"]}
        />
        <DataFileModule
          headerText="Выберите Main Block Image:"
          dataType="mainBlock"
          dataName="image"
          storagePath="data/mainBlock"
          link={mainBlockData.image}
          fileExt={["jpg", "jpeg", "png", "gif", "webp"]}
        />
        <DataModule
          headerText="Main Block Text:"
          dataType="mainBlock"
          dataName="text"
          data={mainBlockText}
        >
          <ServiseInput
            value={mainBlockText}
            onChange={(e) => setMainBlockText(e.target.value)}
          />
        </DataModule>
        <DataModule
          headerText="Main Block List:"
          dataType="mainBlock"
          dataName="list"
          data={mainBlockList}
        >
          <div className={styles.list}>
            {mainBlockList !== undefined && mainBlockList.map((item, index) => (
              <div className={styles.list__item} key={index}>
                <ServiseInput
                  value={item}
                  onChange={(e) => changeMainBlockListItem(index, e.target.value)}
                />
                <MdDelete
                  className={styles.buttonDelete}
                  onClick={() => deleteMainBlockListItem(index)}
                />
              </div>
            ))}
            <div className={styles.buttonContainer}>
              <Button
                className={styles.buttonAdd}
                text="+"
                onClick={addMainBlockListItem}
              />
            </div>
          </div>
        </DataModule>
      </div>
    </div>
  )
}

export default MainBlockData