import React from 'react'
import styles from './AudioEditor.module.scss'
import { FaWindowClose } from 'react-icons/fa'
import FileUpload from '../../FileUpload/FileUpload'

const AudioEditor = ({ changeContent, onClose, content = {}, infoForPath }) => {

  const saveLink = (link) => {
    changeContent({ link: link })
  }

  return (
    <div className={styles.editor}>
      <div className={styles.header}>
        <div className={styles.title}>Загрузите аудиофайл:</div>
        <FaWindowClose
          className={styles.close}
          onClick={() => onClose()}
        />
      </div>
      <FileUpload
        storagePath={`audio/${infoForPath.type}/${infoForPath.name}`}
        oldLink={content.link}
        getLink={(link) => { saveLink(link) }}
        fileExt={["mp3", "wav", "ogg"]}
      />
    </div>
  )
}

export default AudioEditor