import React, { useEffect, useState } from 'react';
import styles from './CreationPanel.module.scss'
import {
  FaArrowAltCircleLeft, FaArrowAltCircleRight, FaFileAlt, FaFileAudio,
  FaFileCode,
  FaFileImage, FaFileVideo
} from 'react-icons/fa';
import {
  AUDIO, EXERSIZE_PININ_1, EXERSIZE_PININ_2, HTML, IMAGE,
  NEXT_STEP_BUTTON, PREV_STEP_BUTTON, QUIZ_TEXT_INPUT,
  TEST_CHECKBOX, TEST_RADIO,
  TEXT, VIDEO,
  YOUTUBE
} from '../../../utils/contentTypes';
import { BsUiChecks, BsUiRadios } from 'react-icons/bs';
import { LuTextCursorInput } from 'react-icons/lu';
import ContentBlockAdmin from '../../Common/ContentBlockAdmin/ContentBlockAdmin';
import { TfiYoutube } from 'react-icons/tfi';

const CreationPanel = ({ onSave, reset, index, modules, infoForPath}) => {

  const [editorType, setEditorType] = useState("")

  const handleCreateContent = (value, contentType) => {
    onSave(value, contentType)
    setEditorType("")
  }

  useEffect(() => {
    if (reset) {
      setEditorType("")
    }

  }, [reset])

  return (
    <div className={styles.creationPanel}>
      {editorType !== "" &&
        <ContentBlockAdmin
          index={index}
          contentType={editorType}
          isEditorOn={true}
          onSave={(value, contentType) => handleCreateContent(value, contentType)}
          onClose={() => { setEditorType("") }}
          infoForPath={infoForPath}
        />
      }
      {editorType === "" &&
        <div className={styles.options}>
          {/* ----- Контенты ----- */}
          {modules.includes(TEXT) && (
            <FaFileAlt
              className={styles.icon}
              onClick={() => setEditorType(TEXT)}
              title="Text"
            />
          )}
          {modules.includes(IMAGE) && (
            <FaFileImage
              className={styles.icon}
              onClick={() => setEditorType(IMAGE)}
              title="Image"
            />
          )}
          {modules.includes(AUDIO) && (
            <FaFileAudio
              className={styles.icon}
              onClick={() => setEditorType(AUDIO)}
              title="Audio"
            />
          )}
          {modules.includes(VIDEO) && (
            <FaFileVideo
              className={styles.icon}
              onClick={() => setEditorType(VIDEO)}
              title="Video"
            />
          )}
            {modules.includes(YOUTUBE) && (
            <TfiYoutube
              className={styles.icon}
              onClick={() => setEditorType(YOUTUBE)}
              title="YouTube"
            />
          )}
            {modules.includes(HTML) && (
            <FaFileCode
              className={styles.icon}
              onClick={() => setEditorType(HTML)}
              title="HTML-code"
            />
          )}
          {/* ----- Задания ------ */}
          {modules.includes(TEST_RADIO) && (
            <BsUiRadios
              className={styles.icon}
              onClick={() => setEditorType(TEST_RADIO)}
              title="Radio Test"
            />
          )}
          {modules.includes(TEST_CHECKBOX) && (
            <BsUiChecks
              className={styles.icon}
              onClick={() => setEditorType(TEST_CHECKBOX)}
              title="Checkbox Test"
            />
          )}
          {modules.includes(QUIZ_TEXT_INPUT) && (
            <LuTextCursorInput
              className={styles.icon}
              onClick={() => setEditorType(QUIZ_TEXT_INPUT)}
              title="Quiz Text Input"
            />
          )}
          {modules.includes(EXERSIZE_PININ_1) && (
            <div
              className={styles.icon + " " + styles.icon_text}
              onClick={() => setEditorType(EXERSIZE_PININ_1)}
            >P1</div>
          )}
          {modules.includes(EXERSIZE_PININ_2) && (
            <div
              className={styles.icon + " " + styles.icon_text}
              onClick={() => setEditorType(EXERSIZE_PININ_2)}
            >P2</div>
          )}
          {/* ----- Прочее ------ */}
          {modules.includes(PREV_STEP_BUTTON) && (
            <FaArrowAltCircleLeft
              className={styles.icon + " " + styles.icon_arrow}
              onClick={() => handleCreateContent(NaN, PREV_STEP_BUTTON)}
              title="Previous Step"
            />
          )}
          {modules.includes(NEXT_STEP_BUTTON) && (
            <FaArrowAltCircleRight
              className={styles.icon + " " + styles.icon_arrow}
              onClick={() => handleCreateContent(NaN, NEXT_STEP_BUTTON)}
              title="Next Step"
            />
          )}
        </div>
      }
    </div>
  );
};

export default CreationPanel;