import { createSlice } from '@reduxjs/toolkit';

const initialState = {
  courseID: "",
  courseName: "",
  courseDescription: "",
  courseImage: "",
  stepNumber: 0,
  steps: [],
};

const courseSlice = createSlice({
  name: 'course',
  initialState,
  reducers: {
    
    setCourse: (state, action) => {
      state.courseID = action.payload.courseID
      state.courseName = action.payload.courseName
      state.courseDescription = action.payload.courseDescription
      state.courseImage = action.payload.courseImage
      state.stepNumber = 0
      state.steps = action.payload.steps
    },

    saveModule: (state, action) => {
      state.steps[action.payload.stepNumber].modules[action.payload.moduleNumber] = action.payload.module
    },

    setStepNumber: (state, action) => {
      state.stepNumber = action.payload.stepNumber
    },

    moveUpModule: (state, action) => {
      const currentModule = state.steps[state.stepNumber].modules[action.payload.moduleNumber]
      const previousModule = state.steps[state.stepNumber].modules[action.payload.moduleNumber - 1]

      state.steps[state.stepNumber].modules[action.payload.moduleNumber] = previousModule
      state.steps[state.stepNumber].modules[action.payload.moduleNumber - 1] = currentModule
    },

    moveDownModule: (state, action) => {
      const currentModule = state.steps[state.stepNumber].modules[action.payload.moduleNumber]
      const nextModule = state.steps[state.stepNumber].modules[action.payload.moduleNumber + 1]

      state.steps[state.stepNumber].modules[action.payload.moduleNumber] = nextModule
      state.steps[state.stepNumber].modules[action.payload.moduleNumber + 1] = currentModule
    },

    deleteModule: (state, action) => {
      state.steps[state.stepNumber].modules.splice(action.payload.moduleNumber, 1)
    },

    addStep: (state, action) => {
      state.steps.push({ stepName: `Step ${state.stepNumber + 1}`, modules: [] })
    },

    renameStep: (state, action) => {
      state.steps[action.payload.stepIndex].stepName = action.payload.newStepName
    },

    moveUpStep: (state, action) => {
      const currentStep = state.steps[action.payload.stepNumber]
      const previousStep = state.steps[action.payload.stepNumber - 1]

      state.steps[action.payload.stepNumber] = previousStep
      state.steps[action.payload.stepNumber - 1] = currentStep

      // перестройка выбраного степа 
      if (action.payload.stepNumber === state.stepNumber) {
        state.stepNumber = state.stepNumber - 1
      } else if (action.payload.stepNumber === state.stepNumber + 1) {
        state.stepNumber = state.stepNumber + 1
      }
    },

    moveDownStep: (state, action) => {
      const currentStep = state.steps[action.payload.stepNumber]
      const nextStep = state.steps[action.payload.stepNumber + 1]

      state.steps[action.payload.stepNumber] = nextStep
      state.steps[action.payload.stepNumber + 1] = currentStep

      // перестройка выбраного степа 
      if (action.payload.stepNumber === state.stepNumber) {
        state.stepNumber = state.stepNumber + 1
      } else if (action.payload.stepNumber === state.stepNumber - 1) {
        state.stepNumber = state.stepNumber - 1
      }
    },

    deleteStep: (state, action) => {
      state.steps.splice(action.payload.stepNumber, 1)
    },

    setCourseName: (state, action) => {
      state.courseName = action.payload.courseName
    },

    setCourseImage: (state, action) => {
      state.courseImage = action.payload.courseImage
    },

    setCourseDescription: (state, action) => {
      state.courseDescription = action.payload.courseDescription
    }
  },
});

export const {
  setCourse,
  saveStep,
  setStepNumber,
  saveModule,
  moveUpModule,
  moveDownModule,
  deleteModule,
  addStep,
  renameStep,
  moveUpStep,
  moveDownStep,
  deleteStep,
  setCourseName,
  setCourseDescription,
  setCourseImage,
} = courseSlice.actions;

export default courseSlice.reducer;