import React from 'react'
import styles from './CoursesPage.module.scss'
import CourseCard from '../../Common/CourseCard/CourseCard'
import Container from '../../Common/Container/Container'
import { useDispatch, useSelector } from 'react-redux'
import Button from '../../UI/Button/Button'
import { setCourse } from '../../../store/course/course'
import { useNavigate } from 'react-router-dom'
import { COURSE_CREATOR_PAGE_ROUTE } from '../../../routs'
import Loader from '../../Common/Loading/Loader'

const CoursesPage = () => {

  const navigate = useNavigate()
  const dispatch = useDispatch()
  const courses = useSelector(state => state.courses.courses)
  const isLoadingCourses = useSelector(state => state.courses.isLoadingCourses)

  const createNewCourse = () => {

    dispatch(setCourse({
      courseID: "",
      courseName: "Course name.",
      courseDescription: "Course description.",
      courseImage: "./image/couses/31379ebe.png",
      steps: [],
    }))

    navigate(COURSE_CREATOR_PAGE_ROUTE, { replace: false })
  }

  return (
    <div>
      <Container className={styles.container}>
        <div className={styles.header}>
          <div className={styles.title}>Список курсов</div>
          <Button
            className={styles.createNewCourseButton}
            text="Создать курс"
            onClick={createNewCourse}
          />
        </div>
        {isLoadingCourses && <Loader text="Courses is loading!"/>}
        {!isLoadingCourses &&
          <div className={styles.courses}>
            {courses.map((item, index) => (
              <CourseCard
                key={index}
                courseNumber={index}
                courseID={item.courseID}
                courseName={item.courseName}
                courseDescription={item.courseDescription}
                courseImage={item.courseImage}
              />
            ))}
          </div>
        }
      </Container>
    </div>
  )
}

export default CoursesPage