import React, { useEffect, useState } from 'react'
import styles from './ExersizePinin2Editor.module.scss'
import ServiseInput from '../../../../../UI/ServiseInput/ServiseInput'
import Button from '../../../../../UI/Button/Button'
import { FaWindowClose } from 'react-icons/fa'
import LetterAndTon from '../../../../../Common/LetterAndTon/LetterAndTon'
import ButtonAnswerTon from '../../../../../UI/ButtonAnswerTon/ButtonAnswerTon'
import { tons } from '../../../../../../utils/constForExersizes'

const ExersizePinin2Editor = ({changeContent, onClose, content }) => {

  const [text, setText] = useState(
    content !== undefined ? content.variantAnswers : ""
  )
  const [isEditorTons, setIsEditorTons] = useState(false)
  const [textLetters, setTextLetters] = useState([])
  const [correctTons, setCorrectTons] = useState(
    content !== undefined ? content.correctTons : []
  )
  const [ton, setTon] = useState("")
  const [tonIsSelected, setTonIsSelected] = useState(false)

  const putInInputTon = (index) => {
    // Создаем новый массив, в котором изменяем только элемент с заданным индексом
    setCorrectTons(prevState => {
      return prevState.map((item, i) => {
        if (i === index) return ton
        else return item
      })
    })
    setTonIsSelected(false)
    setTon("")
  }

  useEffect(() => {
    setTextLetters(text.split(''))
    setCorrectTons(Array(textLetters.length).fill(''))
  }, [text, isEditorTons])

  useEffect(() => {
    changeContent({text, correctTons})
  }, [text, correctTons])

  return (
    <div className={styles.puzzleEditor}>
      <div className={styles.header}>
        {!isEditorTons && <div className={styles.text}>Введите текст:</div>}
        {isEditorTons && <div className={styles.text}>Укажите тоны тоны:</div>}
        <FaWindowClose className={styles.close} onClick={() => onClose()} />
      </div>
      {!isEditorTons &&
        <ServiseInput
          type="text"
          value={text}
          onChange={(event) => setText(event.target.value)}
        />
      }
      {isEditorTons &&
        <div className={styles.field}>
          {textLetters.map((item, index) => (
            <LetterAndTon
              key={index}
              letter={item}
              ton={correctTons[index]}
              isAnswer={false}
              onClick={() => putInInputTon(index)}
            />
          ))}
        </div>
      }
      {isEditorTons && <div className={styles.answers}>
        {tons.map((item) => (
          <ButtonAnswerTon
            key={item}
            text={item}
            onClick={(e) => {
              console.log(e.target.textContent)
              setTon(e.target.textContent)
              setTonIsSelected(true)
            }}
            tonIsSelected={tonIsSelected}
            answer2={ton}
            isAnswer={false}
          />
        ))}
      </div>}
      <div className={styles.buttonContainer}>
        {!isEditorTons &&
          <Button text="указать тонны" onClick={() => setIsEditorTons(true)} />
        }
        {isEditorTons &&
          <Button
            text="изменить текст"
            onClick={() => {
              setIsEditorTons(false)
              setCorrectTons(Array(textLetters.length).fill(''))
            }}
          />
        }
      </div>
    </div>
  )
}

export default ExersizePinin2Editor