import { getDownloadURL, ref, uploadBytesResumable, deleteObject } from 'firebase/storage';
import React, { useState } from 'react';
import { storage } from '../../../firebase';
import styles from './FileUpload.module.scss';
import Button from '../Button/Button';

const FileUpload = ({ storagePath, customFileName, getLink, oldLink, fileExt }) => {
  const [file, setFile] = useState(null);
  const [isLoading, setIsLoading] = useState(false);
  const [isSuccessfulLoading, setIsSuccessfulLoading] = useState(false);

  const handleFileChange = (e) => {
    const selectedFile = e.target.files[0];
    
    if (fileExt && !fileExt.includes(selectedFile?.name.split('.').pop().toLowerCase())) {
      alert(`Invalid file type. Only ${fileExt.join(', ')} files are allowed.`);
      setFile(null);
      return;
    }
    
    setFile(selectedFile);
  };

  const handleUpload = () => {
    console.log("download")

    if (!file) {
      alert("Please select a file first!");
      return;
    }

    const fileName = customFileName || file.name;
    const filePath = storagePath ? `${storagePath}/${fileName}` : `files/${fileName}`;
    const storageRef = ref(storage, filePath);
    const uploadTask = uploadBytesResumable(storageRef, file);

    uploadTask.on(
      "state_changed",
      (snapshot) => {
        setIsLoading(true);

      },
      (error) => {
        console.error("Upload failed", error);
        setIsLoading(false);
        setIsSuccessfulLoading(false); // Сбрасываем статус успешной загрузки при ошибке
      },
      async () => {
        const url = await getDownloadURL(uploadTask.snapshot.ref);
        getLink(url);
        setIsLoading(false);
        setIsSuccessfulLoading(true);

        // Удаление старого файла, если передан oldLink
        if (oldLink) {
          const oldFileRef = ref(storage, oldLink);
          deleteObject(oldFileRef)
            .then(() => console.log("Old file deleted successfully"))
            .catch((error) => console.error("Error deleting old file:", error));
        }

        setTimeout(() => {
          setIsSuccessfulLoading(false);
        }, 3000);
      }
    );
  };

  return (
    <div className={styles.container}>
      <input
        type="file"
        onChange={handleFileChange}
        className={styles.inputFile}
        disabled={isLoading || isSuccessfulLoading}
      />
      <Button 
        onClick={handleUpload}
        disabled={isLoading || isSuccessfulLoading}
      >
        {!isLoading && !isSuccessfulLoading && "Upload"}
        {isLoading && !isSuccessfulLoading && "File Loading"}
        {!isLoading && isSuccessfulLoading && "Successful Loading!"}
      </Button>
    </div>
  );
};

export default FileUpload;
