import React from 'react'
import styles from './CoursePage.module.scss'
import { useDispatch, useSelector } from 'react-redux'
import Content from '../../Common/Content/Content'
import Container from '../../Common/Container/Container'
import Button from '../../UI/Button/Button'
import PagingInput from './PagingInput/PagingInput'
import { setStepNumber } from '../../../store/course/course'
import { useNavigate } from 'react-router-dom'
import { COURSE_CREATOR_PAGE_ROUTE } from '../../../routs'

const CoursePage = () => {

  const navigate = useNavigate()
  const dispatch = useDispatch()
  const steps = useSelector(state => state.course.steps)
  const courseName = useSelector(state => state.course.courseName)
  const stepNumber = useSelector(state => state.course.stepNumber)

  const setLastStep = () => {
    if (stepNumber > 0) {
      dispatch(setStepNumber({ stepNumber: stepNumber - 1 }))
    }
  }

  const setNextStep = () => {
    if (stepNumber < steps.length - 1) {
      dispatch(setStepNumber({ stepNumber: stepNumber + 1 }))
    }
  }

  const editCourse = () => {
    navigate(COURSE_CREATOR_PAGE_ROUTE, { replace: false })
  }

  return (
    <div className={styles.coursePage}>
      <Container>
        <div className={styles.courseName}>{courseName}</div>
        <div className={styles.controlPanel}>
          <div className={styles.stepsCount}>
            Steps count: {steps.length}
          </div>
          <div className={styles.paging}>
          <Button
            text="last"
            onClick={setLastStep}
          />
          <PagingInput />
          <Button
            text="next"
            onClick={setNextStep}
          />
          </div>
          <Button 
            text="edit course"
            onClick={editCourse}
          />
        </div>
        <div className={styles.contents}>
          {steps[stepNumber].modules.map((item, index) => (
            <Content key={index}
              contentType={item.contentType}
              content={item.content}
            />
          ))}
        </div>
      </Container>
    </div>
  )
}

export default CoursePage