import { useDispatch, useSelector } from "react-redux";
import { addDoc, collection, deleteDoc, doc, getDocs, setDoc, updateDoc } from "firebase/firestore";
import { setCourses, setIsLoadingCourses, setIsWaitingSaveCourse } from "../store/courses/courses";
import { db } from "../firebase";
import { useState } from "react";
import { setData, setIsLoadingData } from "../store/data/dataSlise";

//////////////////////////////////
//----- DATA ---------------------

//Сохраниение общих данных данных
export const useSaveData = () => {
  const [isWaitingSaveData, setIsWaitingSaveData] = useState(false);
  const [isSuccessfulSaveData, setIsSuccessfulSaveData] = useState(false);

  const savePageData = async (dataType, data) => {
    try {
      setIsWaitingSaveData(true);
      const docRef = doc(db, 'data', dataType);
      await setDoc(docRef, data, { merge: true });
      console.log('Document saved with ID: ', dataType);
      setIsSuccessfulSaveData(true);
      setTimeout(() => {
        setIsSuccessfulSaveData(false);
      }, 3000);
    } catch (e) {
      console.error('Error saving data: ', e);
    } finally {
      setIsWaitingSaveData(false);
    }
  };

  return { savePageData, isWaitingSaveData, isSuccessfulSaveData };
};

//Получение общих данных
export const useData = () => {

  const dispatch = useDispatch();
  const isLoadingData = useSelector(state => state.data.isLoadingCourses);

  const getData = async () => {

    try {

      dispatch(setIsLoadingData({ value: true }));

      const querySnapshot = await getDocs(collection(db, 'data'))
      const allData = {};
      querySnapshot.forEach((doc) => {
        allData[doc.id] = doc.data() 
      });

      dispatch(setData({ data: allData }));
      
    } catch (e) {
      console.error('Ошибка при получении данных: ', e)
    } finally {
      dispatch(setIsLoadingData({ value: false }));
    }
  }

  return { getData, isLoadingData }
};

/////////////////////////////////
//---- COURSES ------------------

//Получение списка курсов
export const useCourseList = () => {
  const dispatch = useDispatch();
  const isLoadingCourses = useSelector(state => state.courses.isLoadingCourses);

  const getCourseList = async () => {
    try {
      dispatch(setIsLoadingCourses({ value: true })); // Установите isLoading в true перед началом загрузки
      const querySnapshot = await getDocs(collection(db, 'courses'));
      const items = querySnapshot.docs.map(doc => ({
        ...doc.data(),
        courseID: doc.id
      }));
      dispatch(setCourses({ courses: items }));
    } catch (error) {
      console.error('Error fetching data: ', error);
    } finally {
      dispatch(setIsLoadingCourses({ value: false })); // Установите isLoading в false после завершения загрузки
    }
  };

  return { getCourseList, isLoadingCourses };
};

//Сохранение курса
export const useSaveCourse = () => {

  const dispatch = useDispatch();
  const { getCourseList } = useCourseList();
  const isWaitingSaveCourse = useSelector(state => state.courses.isWaitingSaveCourse);
  const [isSuccessfulSaveCourse, setIsSuccessfulSaveCourse] = useState(false)

  const saveCourse = async (course) => {
    try {
      dispatch(setIsWaitingSaveCourse({ value: true }));
      if (course.courseID === "") {
        const docRef = await addDoc(collection(db, 'courses'), course);
        console.log('Document written with ID: ', docRef.id);
      } else {
        const docRef = doc(db, 'courses', course.courseID);
        await updateDoc(docRef, course);
        console.log('Document updated with ID: ', course.courseID);
      }

      getCourseList();

      setIsSuccessfulSaveCourse(true)
      setTimeout(() => {
        setIsSuccessfulSaveCourse(false)
      }, 3000)
    } catch (e) {
      console.error('Error saving course: ', e);
    } finally {
      dispatch(setIsWaitingSaveCourse({ value: false })); 
    }
  };

  return { saveCourse, isWaitingSaveCourse, isSuccessfulSaveCourse };
};

//Удаление курса
export const useDeleteCourse = () => {
  const dispatch = useDispatch();

  const deleteCourse = async (courseID, courseName) => {
    let result = window.confirm("Вы уверены что хотите удалить курс?");
    if (!result) return;

    const userInput = prompt('Введите название курса:');
    if (userInput === courseName) {
      // Удаляем курс
      try {
        const docRef = doc(db, 'courses', courseID);
        await deleteDoc(docRef);
        console.log('Документ удален с ID: ', courseID);
      } catch (e) {
        console.error('Ошибка при удалении документа: ', e);
      }

      // Обновляем список курсов
      try {
        const querySnapshot = await getDocs(collection(db, 'courses'));
        const items = querySnapshot.docs.map(doc => ({
          ...doc.data(),
          courseID: doc.id
        }));
        dispatch(setCourses({ courses: items }));
      } catch (error) {
        console.error('Ошибка при получении данных: ', error);
      }
    } else {
      alert("Название курса неверно! Курс не удален!");
    }
  };

  return deleteCourse;
};



