import React, { useEffect, useState } from 'react'
import styles from './ContentBlockAdmin.module.scss'
import ControlPanel from '../../UI/ControlPanel/ControlPanel'
import Content from '../Content/Content'
import {
  AUDIO, EXERSIZE_PININ_1, EXERSIZE_PININ_2, HTML, IMAGE,
  QUIZ_TEXT_INPUT, TEST_CHECKBOX, TEST_RADIO, TEXT, VIDEO,
  YOUTUBE
} from '../../../utils/contentTypes'
import TestRadioEditor from '../../Pages/CourseCreator/StepCreator/QuizEditors/TestRadioEditor/TestRadioEditor'
import TestCheckboxEditor from '../../Pages/CourseCreator/StepCreator/QuizEditors/TestCheckboxEditor/TestCheckboxEditor'
import QuizTextInputEditor from '../../Pages/CourseCreator/StepCreator/QuizEditors/QuizTextInputEditor/QuizTextInputEditor'
import ExersizePininEditor from '../../Pages/CourseCreator/StepCreator/QuizEditors/ExersizePininEditor/ExersizePininEditor'
import ExersizePinin2Editor from '../../Pages/CourseCreator/StepCreator/QuizEditors/ExersizePinin2Editor/ExersizePinin2Editor'
import ImageEditor from '../../UI/Editors/ImageEditor/ImageEditor'
import AudioEditor from '../../UI/Editors/AudioEditor/AudioEditor'
import VideoEditor from '../../UI/Editors/VideoEditor/VideoEditor'
import TextEditor from '../../UI/Editors/TextEditor/TextEditor'
import Button from '../../UI/Button/Button'
import YouTubeEditor from '../../UI/Editors/YouTubeEditor/YouTubeEditor'
import HtmlEditor from '../../UI/Editors/HtmlEditor/HtmlEditor'

const ContentBlockAdmin = ({ isEditorOn, index, onSave, contentType, content, onMoveUp, onMoveDown, onDelete, onClose, reset, infoForPath }) => {

  const [isEditor, setIsEditor] = useState(isEditorOn)
  const [value, setValue] = useState(content)

  const handleAddContent = () => {
    onSave(value, contentType)
    setIsEditor(false)
  }

  const edit = () => {
    setIsEditor(true)
  }

  const closeEditor = () => {
    setIsEditor(false)
    onClose()
  }

  useEffect(() => {
    if (reset) {
      setIsEditor(false)
    }
  }, [reset])

  return (
    <div className={styles.ContentBlockAdmin}>
      {/* ----- Контент ------ */}
      {isEditor && contentType === TEXT &&
        <TextEditor
          changeContent={(value) => setValue(value)}
          content={content}
          onClose={() => { closeEditor() }}
        />
      }
      {isEditor && contentType === IMAGE &&
        <ImageEditor
          changeContent={(value) => setValue(value)}
          content={content}
          onClose={() => { closeEditor() }}
          infoForPath={infoForPath}  //нужно для сохранения файлов в storage
        />
      }
      {isEditor && contentType === AUDIO &&
        <AudioEditor
          changeContent={(value) => setValue(value)}
          content={content}
          onClose={() => { closeEditor() }}
          infoForPath={infoForPath}  //нужно для сохранения файлов в storage
        />
      }
      {isEditor && contentType === VIDEO &&
        <VideoEditor
          changeContent={(value) => setValue(value)}
          content={content}
          onClose={() => { closeEditor() }}
          infoForPath={infoForPath}  //нужно для сохранения файлов в storage
        />
      }
      {isEditor && contentType === YOUTUBE &&
        <YouTubeEditor
          changeContent={(value) => setValue(value)}
          content={content}
          onClose={() => { closeEditor() }}
        />
      }
      {isEditor && contentType === HTML &&
        <HtmlEditor
          changeContent={(value) => setValue(value)}
          content={content}
          onClose={() => { closeEditor() }}
        />
      }
      {/* ----- Упражнения ------ */}
      {isEditor && contentType === TEST_RADIO &&
        <TestRadioEditor
          changeContent={(value) => setValue(value)}
          onClose={() => { closeEditor() }}
          content={content}
        />
      }
      {isEditor && contentType === TEST_CHECKBOX &&
        <TestCheckboxEditor
          changeContent={(value) => setValue(value)}
          onClose={() => { closeEditor() }}
          content={content}
        />
      }
      {isEditor && contentType === QUIZ_TEXT_INPUT &&
        <QuizTextInputEditor
          changeContent={(value) => setValue(value)}
          onClose={() => { closeEditor() }}
          content={content}
        />
      }
      {isEditor && contentType === EXERSIZE_PININ_1 &&
        <ExersizePininEditor
          changeContent={(value) => setValue(value)}
          onClose={() => { closeEditor() }}
          content={content}
        />
      }
      {isEditor && contentType === EXERSIZE_PININ_2 &&
        <ExersizePinin2Editor
          changeContent={(value) => setValue(value)}
          onClose={() => { closeEditor() }}
          content={content}
        />
      }
      {!isEditor &&
        <ControlPanel
          onEdit={() => { edit(index, contentType, content) }}
          onMoveUp={() => onMoveUp()}
          onMoveDown={() => onMoveDown()}
          onDeleteItem={() => onDelete()}
        />
      }
      {!isEditor &&
        <Content
          contentType={contentType}
          content={content}
        />
      }
      {isEditor &&
        <div className={styles.footer}>
          <Button
            text="save"
            onClick={() => handleAddContent()}
          />
        </div>
      }
    </div>
  )
}

export default ContentBlockAdmin