import React, { useEffect, useState } from 'react'
import styles from './SocialsData.module.scss'
import SocialComponent from './SocialComponent/SocialComponent';
import DataModule from '../../DataModule/DataModule';
import { socialIcons } from '../../../../../utils/socialIcons';
import { useSelector } from 'react-redux';

const SocialsData = () => {

  const socialsData = useSelector( state => state.data.data.socials)
  const [socials, setSocials] = useState([])

  const addSocial = (type) => {
    if (socials !== undefined) {
      setSocials([...socials, { type: type, link: 'default_link' }]);
    } else {
      setSocials([{ type: type, link: 'default_link' }]);
    }
  }

  const handelChangeSocial = (index, newLink) => {
    const updatedSocials = socials.map((social, i) =>
      i === index ? { ...social, link: newLink } : social
    );
    setSocials(updatedSocials);
  }

  const handelDeleteSocial = (index) => {
    const updatedSocials = socials.filter((_, i) => i !== index);
    setSocials(updatedSocials);
  }

  useEffect(() => {
    if (socialsData !== undefined) {
      setSocials(socialsData.socialList)
    }
  }, [socialsData])

  return (
    <div className={styles.socialsData}>
      <h2 className={styles.h2}>Socials Data</h2>
      <DataModule
        headerText="Social List:"
        dataType="socials"
        dataName="socialList"
        data={socials}
      >
        <div className={styles.socials}>
          {socials.map((item, index) => (
            <SocialComponent 
              key={index} 
              type={item.type} 
              link={item.link} 
              changeSocial={(newLink) => handelChangeSocial(index, newLink)}
              deleteSocial={() => handelDeleteSocial(index)}
            />
          ))}
        </div>
        <div className={styles.socialIcons}>
          {socialIcons.map((Component, index) => (
            <div className={styles.icon} key={index}>
              <Component.icon key={index} 
                onClick={() => addSocial(Component.type)}
              />
            </div>
          ))}
        </div>
      </DataModule>
    </div>
  )
}

export default SocialsData