import React, { useEffect, useState } from 'react'
import styles from './AboutMeBlockData.module.scss'
import DataModule from '../../DataModule/DataModule'
import ServiseInput from '../../../../UI/ServiseInput/ServiseInput'
import { useSelector } from 'react-redux'
import DataFileModule from '../../DataFileModule/DataFileModule'

const AboutMeBlockData = () => {

  const aboutMeBlockData = useSelector( state => state.data.data.aboutMeBlock)
  const [aboutMeBlockText, setAboutMeBlockText] = useState("")
  const [aboutMeBlockLink, setAboutMeBlockLink] = useState("")

  useEffect(() => {
    if (aboutMeBlockData !== undefined) {
      setAboutMeBlockText(aboutMeBlockData.text)
      setAboutMeBlockLink(aboutMeBlockData.link)
    }
  }, [aboutMeBlockData])

  return (
    <div className={styles.aboutMeBlockData}>
      <h2 className={styles.h2}>AboutMeData</h2>
      <div className={styles.dataModules}>
        <DataFileModule
          headerText="Выберите Image:"
          dataType="aboutMeBlock"
          dataName="image"
          storagePath="data/aboutMeBlock"
          link={aboutMeBlockData.image}
          fileExt={["jpg", "jpeg", "png", "gif", "webp"]}
        />
        <DataModule
          headerText="Text:"
          dataType="aboutMeBlock"
          dataName="text"
          data={aboutMeBlockText}
        >
          <ServiseInput
            value={aboutMeBlockText}
            onChange={(e) => setAboutMeBlockText(e.target.value)}
          />
        </DataModule>
        {/* <DataModule
          headerText="Link on Admin Page:"
          dataType="aboutMeBlock"
          dataName="link"
          data={aboutMeBlockLink}
        >
          <ServiseInput
            value={aboutMeBlockLink}
            onChange={(e) => setAboutMeBlockLink(e.target.value)}
          />
        </DataModule> */}
      </div>
    </div>
  )
}

export default AboutMeBlockData