import React, { useEffect, useState } from 'react'
import styles from './TestRadioEditor.module.scss'
import ServiseInput from '../../../../../UI/ServiseInput/ServiseInput'
import Button from '../../../../../UI/Button/Button'
import { MdDelete } from 'react-icons/md'
import { FaWindowClose } from 'react-icons/fa'

const TestRadioEditor = ({changeContent, onClose, content}) => {

  const [answers, setAnswers] = useState(
    content !== undefined ? content.answers : ["", ""]
  )
  const [correctAnswer, setCorrectAnswer] = useState(
    content !== undefined ? content.correctAnswer : ""
  )

  const handleInputChange = (index, event) => {
    const newAnswers = [...answers];
    newAnswers[index] = event.target.value;
    setAnswers(newAnswers);
  };

  const handleCorrectAnswerInputChange = (event) => {
    setCorrectAnswer(event.target.value)
  }

  const handleAddAnswer = () => {
    setAnswers([...answers, ""]);
  };

  const handleDeleteAnswer = (index) => {
    if (answers.length > 2) {
      const newAnswers = [...answers];
      newAnswers.splice(index, 1);
      setAnswers(newAnswers);
    } else {
      alert("Должно быть больше одного варианта ответа")
    }
  };

  useEffect(() => {
    changeContent({answers, correctAnswer})
  }, [answers, correctAnswer])

  return (
    <div className={styles.puzzleEditor}>
      <div className={styles.header}>
        <div className={styles.text}>Ответы:</div>
        <FaWindowClose
          className={styles.close}
          onClick={() => onClose()}
        />
      </div>
      <div className={styles.answers}>
        {answers.map((item, index) => (
          <div key={index}>
            <div className={styles.icon}>
              <MdDelete
                className={styles.icon__image}
                onClick={() => handleDeleteAnswer(index)}
              />
            </div>
            <ServiseInput
              key={index}
              type="text"
              value={answers[index]}
              onChange={(event) => handleInputChange(index, event)}
            />
          </div>
        ))}
      </div>
      <div className={styles.buttonAdd}>
        <Button text="+" onClick={handleAddAnswer} />
      </div>
      <div className={styles.text}>Правильный ответ:</div>
      <ServiseInput type="text" value={correctAnswer} onChange={handleCorrectAnswerInputChange} />
    </div>
  )
}

export default TestRadioEditor